program='''from collections import Counter, deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    frames = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = [(r, c)]
            seen.add((r, c))
            component = []
            while q:
                y, x = q.pop()
                component.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx))
                        q.append((yy,xx))
            r0 = min(y for y, x in component)
            r1 = max(y for y, x in component)
            c0 = min(x for y, x in component)
            c1 = max(x for y, x in component)
            if r1-r0 >= 2 and c1-c0 >= 2:
                border = {(y,x) for y in range(r0,r1+1) for x in range(c0,c1+1)
                          if y in (r0,r1) or x in (c0,c1)}
                if set(component) == border:
                    frames.append((r0,r1,c0,c1,color,border))
    frame_cells = set().union(*(f[5] for f in frames)) if frames else set()
    dots = Counter(grid[r][c] for r in range(h) for c in range(w)
                   if grid[r][c] != 0 and (r,c) not in frame_cells)
    out = [[0]*w for _ in range(h)]
    for r0,r1,c0,c1,color,border in frames:
        for r,c in border:
            out[r][c] = color
        need = sum((r-r0-1 + c-c0-1) % 2 == 0
                   for r in range(r0+1,r1) for c in range(c0+1,c1))
        fill = next((col for col,n in dots.items() if n == need), None)
        if fill is not None:
            for r in range(r0+1,r1):
                for c in range(c0+1,c1):
                    if (r-r0-1+c-c0-1)%2 == 0:
                        out[r][c] = fill
    return out
'''
